import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

_src = r'''
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAGuard.h>
#include <cuda_runtime.h>
#include <cublas_v2.h>

#define CUBLAS_CHECK(expr) do { cublasStatus_t _s = (expr); if (_s != CUBLAS_STATUS_SUCCESS) { TORCH_CHECK(false, "cuBLAS error: ", (int)_s); } } while(0)

torch::Tensor matmul_cublas(torch::Tensor a, torch::Tensor b) {
    TORCH_CHECK(a.is_cuda() && b.is_cuda(), "inputs must be CUDA tensors");
    TORCH_CHECK(a.scalar_type() == at::kHalf && b.scalar_type() == at::kHalf, "inputs must be fp16");
    TORCH_CHECK(a.dim() == 2 && b.dim() == 2, "inputs must be 2D");
    TORCH_CHECK(a.size(1) == b.size(0), "shape mismatch");
    const auto M64 = a.size(0), K64 = a.size(1), N64 = b.size(1);
    TORCH_CHECK(M64 <= INT_MAX && N64 <= INT_MAX && K64 <= INT_MAX, "dimensions too large");
    int M = (int)M64, N = (int)N64, K = (int)K64;
    auto c = torch::empty({M64, N64}, a.options());
    if (M == 0 || N == 0) return c;
    if (K == 0) { c.zero_(); return c; }

    c10::cuda::CUDAGuard guard(a.device());
    cublasHandle_t handle = at::cuda::getCurrentCUDABlasHandle();
    float alpha = 1.0f, beta = 0.0f;
    // Row-major C[M,N] = A[M,K] @ B[K,N] is computed as a column-major
    // GEMM C_col[N,M] = B_col[N,K] * A_col[K,M].
    CUBLAS_CHECK(cublasGemmEx(handle,
                              CUBLAS_OP_N, CUBLAS_OP_N,
                              N, M, K,
                              &alpha,
                              (const void*)b.data_ptr<at::Half>(), CUDA_R_16F, N,
                              (const void*)a.data_ptr<at::Half>(), CUDA_R_16F, K,
                              &beta,
                              (void*)c.data_ptr<at::Half>(), CUDA_R_16F, N,
                              CUBLAS_COMPUTE_32F,
                              CUBLAS_GEMM_DEFAULT_TENSOR_OP));
    return c;
}
'''

_ext = None

def _get_ext():
    global _ext
    if _ext is None:
        _ext = load_inline(
            name='h100_fp16_gemm_cublas_ext',
            cpp_sources=[_src],
            functions=['matmul_cublas'],
            with_cuda=True,
            extra_cuda_cflags=['-O3'],
            extra_cflags=['-O3'],
            extra_ldflags=['-lcublas'],
            verbose=False,
        )
    return _ext

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        _get_ext()

    def forward(self, a: torch.Tensor, b: torch.Tensor) -> torch.Tensor:
        # cuBLAS call below expects dense row-major matrices.  Making contiguous
        # preserves the Triton contract for arbitrary positive-stride inputs;
        # for the common benchmark path this is a no-op.
        if not a.is_contiguous():
            a = a.contiguous()
        if not b.is_contiguous():
            b = b.contiguous()
        return _get_ext().matmul_cublas(a, b)

